//! Built-in virtual backgrounds. They are generated by this code (gradients, soft lighting
//! and out-of-focus "bokeh" lights), not shipped as image files, so there's nothing to
//! license and they render sharply at any resolution.
//!
//! Rendering is deterministic: the same id and size always give the same pixels.

/// A built-in background the user can pick.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Builtin {
    /// Stable id, stored in settings.
    pub id: &'static str,
    /// Name shown in the UI.
    pub label: &'static str,
}

pub const BUILTINS: &[Builtin] = &[
    Builtin {
        id: "studio",
        label: "Studio",
    },
    Builtin {
        id: "warm-wall",
        label: "Warm wall",
    },
    Builtin {
        id: "dusk",
        label: "Dusk",
    },
    Builtin {
        id: "ocean",
        label: "Ocean",
    },
    Builtin {
        id: "mint",
        label: "Mint",
    },
];

type Rgb = [f32; 3];

const fn hex(c: u32) -> Rgb {
    [
        ((c >> 16) & 0xff) as f32,
        ((c >> 8) & 0xff) as f32,
        (c & 0xff) as f32,
    ]
}

/// Linear interpolation through colour stops `(position, colour)`, positions ascending.
fn gradient(stops: &[(f32, Rgb)], t: f32) -> Rgb {
    let t = t.clamp(0.0, 1.0);
    for pair in stops.windows(2) {
        let ((t0, c0), (t1, c1)) = (pair[0], pair[1]);
        if t <= t1 {
            let f = smooth(((t - t0) / (t1 - t0)).clamp(0.0, 1.0));
            return std::array::from_fn(|i| c0[i] + (c1[i] - c0[i]) * f);
        }
    }
    stops[stops.len() - 1].1
}

fn smooth(t: f32) -> f32 {
    t * t * (3.0 - 2.0 * t)
}

/// Out-of-focus lights scattered over part of the picture.
struct Bokeh {
    count: usize,
    seed: u32,
    /// Colours as 0xRRGGBB.
    colours: &'static [u32],
    /// Radius range as a fraction of the picture height.
    radius: (f32, f32),
    /// Opacity range.
    opacity: (f32, f32),
    /// Vertical band (fractions of the height) the centres fall in.
    band: (f32, f32),
}

struct Style {
    /// Base colour at relative position (u, v), both 0..1 (v down), given the aspect ratio.
    base: fn(u: f32, v: f32, aspect: f32) -> Rgb,
    bokeh: Option<Bokeh>,
    /// Amplitude of the fine grain (in 8-bit steps); also hides gradient banding.
    grain: f32,
}

fn style(id: &str) -> Option<Style> {
    Some(match id {
        // Neutral dark grey with a soft spotlight behind the person: a plain office look.
        "studio" => Style {
            base: |u, v, aspect| {
                let (dx, dy) = ((u - 0.5) * aspect, v - 0.42);
                let d = (dx * dx + dy * dy).sqrt() / (0.25 * aspect * aspect + 0.36).sqrt();
                gradient(
                    &[
                        (0.0, hex(0x5a5c62)),
                        (0.55, hex(0x3a3b40)),
                        (1.0, hex(0x1b1c1f)),
                    ],
                    d,
                )
            },
            bokeh: None,
            grain: 1.5,
        },
        // Painted beige wall lit from the upper left.
        "warm-wall" => Style {
            base: |u, v, aspect| {
                let (dx, dy) = ((u - 0.3) * aspect, v + 0.15);
                let d = (dx * dx + dy * dy).sqrt() / (aspect * aspect + 1.0).sqrt();
                gradient(
                    &[
                        (0.0, hex(0xeadbc4)),
                        (0.55, hex(0xd2bb9c)),
                        (1.0, hex(0xa98e6e)),
                    ],
                    d,
                )
            },
            bokeh: None,
            grain: 2.5,
        },
        // Purple sky fading to an orange horizon, with warm city lights out of focus.
        "dusk" => Style {
            base: |u, v, _| {
                let t = v * 0.85 + (u - 0.5) * 0.15 + 0.075;
                gradient(
                    &[
                        (0.0, hex(0x1f1640)),
                        (0.45, hex(0x5b2a63)),
                        (0.75, hex(0xb4506a)),
                        (1.0, hex(0xe89a6a)),
                    ],
                    t,
                )
            },
            bokeh: Some(Bokeh {
                count: 18,
                seed: 0x0d05_c0de,
                colours: &[0xffc58a, 0xff9e7a, 0xffd9a0, 0xf7a1c4],
                radius: (0.03, 0.10),
                opacity: (0.10, 0.30),
                band: (0.35, 1.0),
            }),
            grain: 1.0,
        },
        // Deep navy to teal, like looking up from under water, with pale aqua lights.
        "ocean" => Style {
            base: |u, v, _| {
                let t = v * 0.65 + u * 0.35;
                gradient(
                    &[
                        (0.0, hex(0x0b1f3f)),
                        (0.5, hex(0x124d6e)),
                        (1.0, hex(0x1d8a86)),
                    ],
                    t,
                )
            },
            bokeh: Some(Bokeh {
                count: 14,
                seed: 0x0cea_0001,
                colours: &[0x9fe7e3, 0x7cc8f0, 0xd2f4f0],
                radius: (0.04, 0.12),
                opacity: (0.06, 0.18),
                band: (0.0, 1.0),
            }),
            grain: 1.0,
        },
        // Light, fresh mint with a few large, faint white lights.
        "mint" => Style {
            base: |u, v, _| {
                let t = v * 0.7 + (1.0 - u) * 0.3;
                gradient(
                    &[
                        (0.0, hex(0xe4f5ec)),
                        (0.55, hex(0xb4e2cc)),
                        (1.0, hex(0x7cc4a6)),
                    ],
                    t,
                )
            },
            bokeh: Some(Bokeh {
                count: 9,
                seed: 0x0000_beef,
                colours: &[0xffffff, 0xf2fff8],
                radius: (0.08, 0.18),
                opacity: (0.10, 0.22),
                band: (0.0, 1.0),
            }),
            grain: 1.0,
        },
        _ => return None,
    })
}

/// Small fixed-seed LCG, for repeatable layouts.
struct Lcg(u32);

impl Lcg {
    /// Next value in 0.0..1.0.
    fn next(&mut self) -> f32 {
        self.0 = self.0.wrapping_mul(1_664_525).wrapping_add(1_013_904_223);
        (self.0 >> 8) as f32 / (1u32 << 24) as f32
    }

    fn range(&mut self, (lo, hi): (f32, f32)) -> f32 {
        lo + (hi - lo) * self.next()
    }
}

/// Hash noise in -0.5..0.5 (deterministic, no sequential state).
fn noise(x: usize, y: usize) -> f32 {
    let mut n = (x as u32).wrapping_mul(0x27d4_eb2d) ^ (y as u32).wrapping_mul(0x1656_67b1);
    n ^= n >> 15;
    n = n.wrapping_mul(0x85eb_ca6b);
    n ^= n >> 13;
    (n >> 8) as f32 / (1u32 << 24) as f32 - 0.5
}

/// The base gradients are smooth, so they're evaluated on a grid this many pixels apart
/// and interpolated in between (keeps 1080p rendering fast, even in debug builds).
const GRID: usize = 8;
/// Side of the repeating grain tile.
const TILE: usize = 64;

/// Renders built-in background `id` as `w*h` RGBA, or `None` for an unknown id.
pub fn render_rgba(id: &str, w: usize, h: usize) -> Option<Vec<u8>> {
    let style = style(id)?;
    let mut out = vec![255u8; w * h * 4];
    if w == 0 || h == 0 {
        return Some(out);
    }
    let aspect = w as f32 / h as f32;

    let (gw, gh) = (w.div_ceil(GRID) + 1, h.div_ceil(GRID) + 1);
    let mut grid = Vec::with_capacity(gw * gh);
    for gy in 0..gh {
        let v = (gy * GRID) as f32 / h as f32;
        for gx in 0..gw {
            grid.push((style.base)((gx * GRID) as f32 / w as f32, v, aspect));
        }
    }
    // Grain, plus 0.5 so the float-to-u8 casts below round.
    let tile: Vec<f32> = (0..TILE * TILE)
        .map(|i| noise(i % TILE, i / TILE) * style.grain + 0.5)
        .collect();

    let step = 1.0 / GRID as f32;
    let mut row = vec![[0.0f32; 3]; gw];
    for (y, line) in out.chunks_exact_mut(w * 4).enumerate() {
        let (gy, ty) = (y / GRID, (y % GRID) as f32 * step);
        let (g0, g1) = (&grid[gy * gw..][..gw], &grid[(gy + 1) * gw..][..gw]);
        for ((r, a), b) in row.iter_mut().zip(g0).zip(g1) {
            *r = [
                a[0] + (b[0] - a[0]) * ty,
                a[1] + (b[1] - a[1]) * ty,
                a[2] + (b[2] - a[2]) * ty,
            ];
        }
        let grain = &tile[(y % TILE) * TILE..][..TILE];
        for (gx, cells) in line.chunks_mut(GRID * 4).enumerate() {
            let (mut col, next) = (row[gx], row[gx + 1]);
            let d = [
                (next[0] - col[0]) * step,
                (next[1] - col[1]) * step,
                (next[2] - col[2]) * step,
            ];
            for (k, px) in cells.as_chunks_mut::<4>().0.iter_mut().enumerate() {
                let n = grain[(gx * GRID + k) % TILE];
                px[0] = (col[0] + n).clamp(0.0, 255.0) as u8;
                px[1] = (col[1] + n).clamp(0.0, 255.0) as u8;
                px[2] = (col[2] + n).clamp(0.0, 255.0) as u8;
                col[0] += d[0];
                col[1] += d[1];
                col[2] += d[2];
            }
        }
    }

    if let Some(b) = &style.bokeh {
        let mut rng = Lcg(b.seed);
        for _ in 0..b.count {
            let cx = rng.next() * w as f32;
            let cy = rng.range(b.band) * h as f32;
            let r = (rng.range(b.radius) * h as f32).max(1.0);
            let opacity = rng.range(b.opacity);
            let colour =
                hex(b.colours[(rng.next() * b.colours.len() as f32) as usize % b.colours.len()]);
            let x0 = (cx - r).floor().max(0.0) as usize;
            let x1 = ((cx + r).ceil().max(0.0) as usize).min(w);
            let y0 = (cy - r).floor().max(0.0) as usize;
            let y1 = ((cy + r).ceil().max(0.0) as usize).min(h);
            for y in y0..y1 {
                let dy = (y as f32 + 0.5 - cy) / r;
                for x in x0..x1 {
                    let dx = (x as f32 + 0.5 - cx) / r;
                    let d2 = dx * dx + dy * dy;
                    if d2 >= 1.0 {
                        continue;
                    }
                    // Flat disc with a soft edge and a slightly brighter rim, like a real
                    // out-of-focus highlight.
                    let d = d2.sqrt();
                    let edge = 1.0 - smooth(((d - 0.82) / 0.18).clamp(0.0, 1.0));
                    let a = opacity * edge * (0.85 + 0.15 * d);
                    let px = &mut out[(y * w + x) * 4..][..3];
                    for c in 0..3 {
                        let v = px[c] as f32;
                        px[c] = (v + (colour[c] - v) * a + 0.5) as u8;
                    }
                }
            }
        }
    }
    Some(out)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_builtin_renders_the_right_length() {
        for b in BUILTINS {
            for (w, h) in [(1920, 1080), (640, 480), (7, 3), (1, 1), (0, 0)] {
                let img = render_rgba(b.id, w, h).unwrap_or_else(|| panic!("{} missing", b.id));
                assert_eq!(img.len(), w * h * 4, "{} at {w}x{h}", b.id);
                assert!(img.as_chunks::<4>().0.iter().all(|p| p[3] == 255));
            }
        }
    }

    #[test]
    fn ids_are_unique_and_unknown_is_none() {
        for (i, a) in BUILTINS.iter().enumerate() {
            assert!(BUILTINS[i + 1..].iter().all(|b| b.id != a.id));
        }
        assert!(render_rgba("nope", 16, 9).is_none());
    }

    #[test]
    fn different_ids_differ_and_rendering_is_deterministic() {
        let imgs: Vec<_> = BUILTINS
            .iter()
            .map(|b| render_rgba(b.id, 160, 90).unwrap())
            .collect();
        for (i, a) in imgs.iter().enumerate() {
            for b in &imgs[i + 1..] {
                assert_ne!(a, b);
            }
        }
        assert_eq!(render_rgba("dusk", 160, 90).unwrap(), imgs[2]);
    }

    #[test]
    fn backgrounds_are_not_flat() {
        for b in BUILTINS {
            let img = render_rgba(b.id, 320, 180).unwrap();
            let lum: Vec<u32> = img
                .as_chunks::<4>()
                .0
                .iter()
                .map(|p| p[0] as u32 + p[1] as u32 + p[2] as u32)
                .collect();
            let (lo, hi) = (lum.iter().min().unwrap(), lum.iter().max().unwrap());
            assert!(hi - lo > 30, "{} is nearly flat", b.id);
        }
    }
}
